const NOTE_SELECT = `SELECT n.id, n.owner_id, u.email AS owner_email, n.title, n.body, n.created_at
  FROM notes n JOIN users u ON u.id = n.owner_id`;

function parseId(raw) {
  return /^\d{1,9}$/.test(raw) ? Number(raw) : null;
