    }
    const [note] = db.run('INSERT INTO notes (owner_id, title, body, created_at) VALUES (?, ?, ?, ?) RETURNING id', [
      req.user.id, title.slice(0, 200), body.slice(0, 20000), new Date().toISOString(),
    ]);
